void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float rippleSpeed = 0.5;      // Speed of ripple expansion
    float rippleStrength = 0.1;   // Maximum ripple strength
    float rippleWidth = 0.05;     // Width of each ripple effect
    float rippleInterval = 4.0;   // Time interval between ripples
    float rippleSmoothing = 0.06;

    vec2 uv = fragCoord / iResolution.xy;
    vec2 center = vec2(0.5);  // Center of the ripple

    float rad = length(uv - center);

    float timeOffset = mod(iTime, rippleInterval);  // Time within current ripple cycle
    float rippleDistance = abs(rad - timeOffset * rippleSpeed);

    // Use a smoothstep to create a fading effect for the ripple
    float rippleFade = smoothstep(rippleWidth, rippleWidth + rippleSmoothing, rippleDistance);

    // Apply ripple effect by distorting UV coordinates
    if (rad < 0.7) {
        uv = uv + rippleFade * (uv - center) * 0.05;  // Distort UVs based on ripple
    }

    // Sample texture based on new UV coordinates
    vec3 col = texture(iChannel0, uv).xyz;

    // Output final color
    fragColor = vec4(col, 1.0);
}
